#!/usr/bin/env node
// generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
// Собирает индекс технического долга memory/tech-debt/tech-debt.md из файлов-пунктов
// memory/tech-debt/NNN-*.md. Пункт — отдельный файл с frontmatter: status, area, checked,
// а в workspace с несколькими репозиториями ещё repo — какие репозитории projects/ он касается
// (через запятую; `workspace` — корень: конфигурация команды, память). Индекс руками
// не правится, только перегенерируется.
//
//   node .claude/bin/tech-debt-index.mjs            — перезаписать индекс
//   node .claude/bin/tech-debt-index.mjs --check    — код 1, если индекс отстал от файлов
//
// Корень workspace — каталог над .claude/, либо WORKSPACE_ROOT (для фикстур).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { findRoot, loadWorkspace } from './lib/workspace.mjs';

if (process.argv[2] === '-h' || process.argv[2] === '--help') {
  const lines = fs.readFileSync(fileURLToPath(import.meta.url), 'utf8').split('\n').slice(2);
  const end = lines.findIndex((l) => !l.startsWith('//'));
  process.stdout.write(lines.slice(0, end).map((l) => l.replace(/^\/\/ ?/, '')).join('\n') + '\n');
  process.exit(0);
}

const here = path.dirname(fileURLToPath(import.meta.url));
const root = findRoot(here);
const ws = loadWorkspace(root);
const fatals = ws.problems.filter((p) => p.fatal);
if (fatals.length) {
  for (const p of fatals) console.error(`.claude/workspace.json: ${p.msg}`);
  process.exit(2);
}
const dir = path.join(root, 'memory', 'tech-debt');
const indexPath = path.join(dir, 'tech-debt.md');
const check = process.argv.includes('--check');

const STATUSES = ['открыт', 'частично', 'под сомнением', 'закрыт', 'снят'];

// Один репозиторий — поле repo ничего не различает и не требуется. Несколько — без него пункт
// не найти по репозиторию, а имя сверяется с projects/: опечатка иначе молча уводит пункт из выборки.
const repoNames = ws.repos.map((r) => r.name);
const multiRepo = repoNames.length > 1;
const repoList = (v) => (v || '').split(',').map((x) => x.trim()).filter(Boolean);

// Каталога нет у свежей сборки: пустой каталог git не хранит, и первый пункт долга появится позже.
// Индекс создаётся сразу — на него ссылается memory/MEMORY.md.
if (!fs.existsSync(dir)) {
  if (check) {
    console.log('memory/tech-debt/ нет — проверять нечего');
    process.exit(0);
  }
  fs.mkdirSync(dir, { recursive: true });
}

function parseItem(file) {
  const text = fs.readFileSync(path.join(dir, file), 'utf8');
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/);
  if (!m) return { file, error: 'нет frontmatter' };
  const meta = {};
  for (const line of m[1].split(/\r?\n/)) {
    const kv = line.match(/^\s*([a-z_]+):\s*(.*)$/);
    if (kv) meta[kv[1]] = kv[2].replace(/^"(.*)"$/, '$1');
  }
  const h1 = m[2].match(/^# ([0-9]+[а-я]?)\. (.*)$/mu);
  if (!h1) return { file, error: 'нет заголовка вида «# N. …»' };
  const errors = [];
  if (!meta.status) errors.push('нет status');
  else if (!STATUSES.includes(meta.status)) errors.push(`status «${meta.status}» вне легенды`);
  if (!meta.area) errors.push('нет area');
  if (multiRepo) {
    const listed = repoList(meta.repo);
    if (listed.length === 0) errors.push('нет repo — репозиториев в workspace несколько');
    for (const r of listed) if (r !== 'workspace' && !repoNames.includes(r)) errors.push(`repo «${r}» — такого репозитория в projects/ нет`);
  }
  const numInFile = file.match(/^(\d{3}[a-z]?)-/)?.[1];
  const expected = numKey(h1[1]);
  if (numInFile !== expected) errors.push(`номер в имени ${numInFile} не совпадает с заголовком ${h1[1]}`);
  return { file, num: h1[1], key: expected, title: h1[2], ...meta, error: errors.join('; ') || null };
}

// Буквенный суффикс в заголовке кириллический (20б), в имени файла — латинский (020b).
function numKey(n) {
  const mm = n.match(/^(\d+)([а-я]?)$/u);
  const suffix = mm[2] ? ({ а: 'a', б: 'b', в: 'v' }[mm[2]] ?? mm[2]) : '';
  return `${mm[1].padStart(3, '0')}${suffix}`;
}

const files = fs.readdirSync(dir).filter((f) => /^\d{3}[a-z]?-.*\.md$/.test(f)).sort();
const items = files.map(parseItem);
const broken = items.filter((i) => i.error);
if (broken.length) {
  for (const b of broken) console.error(`${path.relative(root, path.join(dir, b.file)).replace(/\\/g, '/')}: ${b.error}`);
  process.exit(2);
}

const counts = Object.fromEntries(STATUSES.map((s) => [s, 0]));
for (const i of items) counts[i.status]++;

const rows = items.map((i) => {
  const note = i.status_note ? ` — ${i.status_note}` : '';
  const repo = multiRepo ? ` ${repoList(i.repo).join(', ')} |` : '';
  return `| ${i.num} | ${i.status}${note} | ${i.area} |${repo} [${i.title.replace(/\|/g, '\\|')}](${i.file}) | ${i.checked ?? ''} |`;
});

const out = `---
name: tech-debt
description: Индекс технического долга — файл на пункт в memory/tech-debt/, генерируется скриптом .claude/bin/tech-debt-index.mjs
metadata:
  type: project
---

# Технический долг

Отличие от \`issues/\`: там места, где неосторожная правка стоит дорого. Здесь — то, что надо
починить, с планом и тем, чем подтверждено.

**Пункт — отдельный файл \`NNN-<slug>.md\`** с frontmatter: \`status\`, \`status_note\`, \`area\`,
\`checked\` (дата последней проверки по коду)${multiRepo ? ', \`repo\` — репозитории \`projects/\` через запятую, \`workspace\` — корень' : ''}. Новый пункт — следующий номер за
последним в этом списке, статус \`открыт\`; буквенный суффикс (\`20б\`) допустим только у уже
существующих. Пункт снимается, когда изменился код в ветке по умолчанию на \`origin\`, а не когда работу взяли.

Статусы: \`открыт\` · \`частично\` (в \`status_note\` — что осталось) · \`под сомнением\` (дефект
не подтверждён или фикс в невлитой ветке) · \`закрыт\` (дата или задача в \`status_note\`) ·
\`снят\` (предпосылка умерла, риск принят, дубль).

**Этот файл генерируется:** \`node .claude/bin/tech-debt-index.mjs\`; проверка актуальности —
тот же скрипт с \`--check\`. Правки руками здесь затираются.

Пунктов: ${items.length} — открыт ${counts['открыт']}, частично ${counts['частично']}, под сомнением ${counts['под сомнением']}, закрыт ${counts['закрыт']}, снят ${counts['снят']}.

${multiRepo ? '| № | Статус | Область | Репозиторий | Пункт | Проверено |\n|---|---|---|---|---|---|' : '| № | Статус | Область | Пункт | Проверено |\n|---|---|---|---|---|'}
${rows.join('\n')}
`;

if (check) {
  const current = fs.existsSync(indexPath) ? fs.readFileSync(indexPath, 'utf8').replace(/\r\n/g, '\n') : '';
  if (current !== out) {
    console.error(`${path.relative(root, indexPath).replace(/\\/g, '/')} отстал от файлов-пунктов: перегенерируй node .claude/bin/tech-debt-index.mjs`);
    process.exit(1);
  }
  console.log(`tech-debt index ok: ${items.length} пунктов`);
  process.exit(0);
}

fs.writeFileSync(indexPath, out, 'utf8');
console.log(`${path.relative(root, indexPath).replace(/\\/g, '/')}: ${items.length} пунктов`);
